// Nonlinear MPC on the single-rigid-body model: computes the ground reaction forces of a quadruped.
// Standalone class: no ROS node, no topics. Uses the acados solver generated by scripts/generate_solver.py.
#pragma once

#include <memory>
#include <string>
#include <vector>

#include "robodog_nmpc/config.hpp"
#include "robodog_nmpc/types.hpp"

namespace robodog_nmpc {

// Usage:
//   NmpcSolver mpc;
//   if (mpc.initialize(path) != Status::Ok) { std::cerr << mpc.errorMessage(); ... }
// Not thread-safe: use one instance per control thread. Not copyable or movable (owns the acados solver);
// hold it in a std::unique_ptr if it has to be moved.
class NmpcSolver {
 public:
  NmpcSolver();
  ~NmpcSolver();
  NmpcSolver(const NmpcSolver&) = delete;
  NmpcSolver& operator=(const NmpcSolver&) = delete;

  // Load and validate config.yaml, check it against the generated solver, create the acados solver and apply
  // the [runtime] settings. Can be called again (e.g. to reload the config); on failure the object is unusable
  // until the next successful initialize().
  Status initialize(const std::string& config_path);

  // One control step: one SQP-RTI iteration, warm-started from the previous plan. The result (forces to apply
  // now, u_0) is in getSolution(). No memory allocation, no exceptions, no file access.
  // Returns Ok, NotInitialized, InvalidInput (nothing solved) or SolverFailed. For InvalidInput and SolverFailed
  // the forces are the next step of the last successful plan (feet in swing now get zero force), or zero if
  // there is no such plan.
  //
  // (a) contact flags and foot positions held over the whole horizon (task-literal form).
  Status run(const State& state, const Command& cmd, const Contact& contact, const FootPositions& feet);

  // (c) full form: contact schedule for the N intervals and foot positions for the N + 1 nodes, from the caller.
  Status run(const State& state, const Command& cmd, const std::vector<Contact>& contact_schedule,
             const std::vector<FootPositions>& foot_plan);

  bool isInitialized() const;
  const Solution& getSolution() const;      // result of the last run()
  const std::string& errorMessage() const;  // details of the last non-Ok status ("" after Ok)
  const Config& config() const;             // the loaded configuration (valid after initialize() returned Ok)
  int horizonLength() const;                // N of the compiled-in solver

 private:
  struct Impl;
  std::unique_ptr<Impl> impl_;
};

}  // namespace robodog_nmpc
